package com.hms.appointments;
import com.hms.billing.*; import com.hms.patients.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class BookingPolicyService {private final TenantSubscriptionRepository subscriptions;private final PatientIdentifierSettingsRepository identifiers;private final AppointmentRepository appointments;public BookingPolicyService(TenantSubscriptionRepository s,PatientIdentifierSettingsRepository i,AppointmentRepository a){subscriptions=s;identifiers=i;appointments=a;} public void validate(UUID tenant,CreateAppointmentRequest r){subscriptions.findById(tenant).ifPresent(s->{if(s.getStatus()==SubscriptionStatus.PAUSED||s.getStatus()==SubscriptionStatus.CANCELLED)throw new IllegalArgumentException("Hospital subscription does not accept appointments");if(s.getAppointmentLimit()!=null&&appointments.findAllByTenantIdOrderByStartsAtAsc(tenant).stream().filter(a->a.getStatus()!=AppointmentStatus.CANCELLED).count()>=s.getAppointmentLimit())throw new IllegalArgumentException("Hospital appointment limit has been reached");});identifiers.findByTenantId(tenant).ifPresent(i->{if(i.isHospitalIdentifierRequired()&&(r.hospitalPatientId()==null||r.hospitalPatientId().isBlank()))throw new IllegalArgumentException("Hospital patient ID is required");if(i.isAbhaRequired()&&!i.isAbhaEnabled())throw new IllegalArgumentException("ABHA is not enabled");if(i.isAbhaRequired()&&(r.abhaId()==null||r.abhaId().isBlank()))throw new IllegalArgumentException("ABHA ID is required");});}}
